// ─────────────────────────────────────────────────────────────
// EDIT THESE BEFORE ACTIVATING — same values in all three workflows
// ─────────────────────────────────────────────────────────────
const APP_URL        = 'https://YOUR-APP.vercel.app';
const WEBHOOK_SECRET = 'CHANGE_ME_same_as_N8N_WEBHOOK_SECRET';
const SUPABASE_URL   = 'https://YOUR-PROJECT.supabase.co';
const SUPABASE_KEY   = 'YOUR_SERVICE_ROLE_KEY';
const SCRAPER_URL    = 'https://YOUR-SCRAPER.vercel.app';
const SCRAPER_SECRET = 'CHANGE_ME_same_as_SCRAPER_SECRET';

// Listings pulled per search term, per source.
const LIMIT_PER_TERM = 40;

// Company slugs for the ATS sources — first-party listings, free, but you have
// to name the companies. Grow this list over time.
const ATS = { greenhouse: [], ashby: [], workable: [] };

// Jobs sent to the model in one request.
const SCORE_BATCH_SIZE = 15;

const MODELS = {
  anthropic: 'claude-opus-5',
  openai:    'gpt-4o-mini',
  gemini:    'gemini-2.0-flash',
  groq:      'llama-3.3-70b-versatile'
};

return { json: {
  appUrl: APP_URL, webhookSecret: WEBHOOK_SECRET,
  supabaseUrl: SUPABASE_URL, supabaseKey: SUPABASE_KEY,
  scraperUrl: SCRAPER_URL, scraperSecret: SCRAPER_SECRET,
  limitPerTerm: LIMIT_PER_TERM, ats: ATS,
  scoreBatchSize: SCORE_BATCH_SIZE, models: MODELS
} };

// Both entry points converge here. A webhook run carries one userId; the
// nightly run carries none, and the app answers with the batch due a pass.
const config = $('Set Config').first().json;
let userId = null;
try { userId = $('On Demand').first().json.body?.userId || null; } catch (e) { /* scheduled run */ }

return [{ json: { ...config, userId, onDemand: Boolean(userId) } }];

const payload = $input.first().json;
const body = payload.body || payload;

// On-demand: the app already returned this user's candidates in full.
if (body.userId) return [{ json: { userId: body.userId, preloaded: body } }];

const users = body.users || [];
console.log('Nightly top-up for ' + users.length + ' user(s)');
return users.map(u => ({ json: { userId: u.userId, preloaded: null } }));

// The SQL pre-filter has already dropped everything irrelevant and everything
// this user has seen, so what arrives here is exactly what is worth paying a
// model to read.
const payload = $input.first().json;
const data = payload.body || payload;
const size = $('Set Config').first().json.scoreBatchSize || 15;

if (!data.jobs || data.jobs.length === 0) {
  console.log('No new candidates for ' + (data.userId || '?'));
  return [];
}
console.log('Scoring ' + data.jobs.length + ' candidate(s) for ' + data.userId);

const batches = [];
for (let i = 0; i < data.jobs.length; i += size) {
  batches.push({ json: {
    userId: data.userId, aiProvider: data.aiProvider, aiApiKey: data.aiApiKey,
    aiModel: $('Set Config').first().json.models[data.aiProvider],
    profile: data.profile, jobs: data.jobs.slice(i, i + size)
  } });
}
return batches;

// One node builds the request for whichever provider the user connected, so a
// single HTTP node serves all four.
const b = $input.item.json;
const p = b.profile || {};

const profile = [
  'Field: ' + (p.field || 'n/a'),
  'Target titles: ' + ((p.jobTitles || []).join(', ') || '(any)'),
  'Skills: ' + ((p.skills || []).join(', ') || '(not given)'),
  'Experience: ' + (p.experience || 0) + ' years (' + (p.seniority || 'mid') + ')',
  'Work preference: ' + ((p.workPreference || []).join(', ') || 'any'),
  'Location: ' + (p.location?.worldwide ? 'Worldwide' : (p.location?.countries || []).join(', ') || 'Worldwide')
].join('\n');

const listing = b.jobs.map((j, i) => ({
  i, title: String(j.title || '').substring(0, 200),
  company: String(j.company || '').substring(0, 120),
  location: String(j.location || '').substring(0, 120),
  type: j.job_type,
  description: String(j.description || '').substring(0, 900)
}));

const instruction = 'Score each job against the candidate profile.\n\n'
  + 'CANDIDATE PROFILE:\n' + profile + '\n\n'
  + 'JOBS (JSON):\n' + JSON.stringify(listing) + '\n\n'
  + 'Return ONLY {"results":[...]} with one entry per job:\n'
  + '{"i": <index>, "score": <0-100>, "tech_stack": ["lowercase"], '
  + '"seniority": "junior"|"mid"|"senior"|"lead"|null, "is_relevant": <bool>, '
  + '"match_reason": "<max 20 words>"}\n\n'
  + 'Scoring: 90-100 near-perfect; 70-89 good; 50-69 partial; 30-49 weak; 0-29 poor.\n'
  + 'Set is_relevant false only for a completely unrelated field or recruiter spam.\n'
  + 'Return an entry for every job, in order.';

const system = 'You are a job matching engine. Return only strict JSON. No markdown, no preamble.';
let aiUrl, aiHeaders, aiBody;

switch (b.aiProvider) {
  case 'anthropic':
    aiUrl = 'https://api.anthropic.com/v1/messages';
    aiHeaders = { 'x-api-key': b.aiApiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' };
    // No `temperature`: sampling parameters are rejected with a 400 on current
    // Opus/Sonnet models. `effort: low` keeps a classification task cheap.
    aiBody = { model: b.aiModel, max_tokens: 4000, system,
               output_config: { effort: 'low' },
               messages: [{ role: 'user', content: instruction }] };
    break;
  case 'gemini':
    aiUrl = 'https://generativelanguage.googleapis.com/v1beta/models/' + b.aiModel + ':generateContent';
    aiHeaders = { 'x-goog-api-key': b.aiApiKey, 'Content-Type': 'application/json' };
    aiBody = { systemInstruction: { parts: [{ text: system }] },
               contents: [{ role: 'user', parts: [{ text: instruction }] }],
               generationConfig: { temperature: 0, responseMimeType: 'application/json', maxOutputTokens: 4000 } };
    break;
  case 'openai':
  case 'groq':
  default:
    aiUrl = b.aiProvider === 'openai'
      ? 'https://api.openai.com/v1/chat/completions'
      : 'https://api.groq.com/openai/v1/chat/completions';
    aiHeaders = { 'Authorization': 'Bearer ' + b.aiApiKey, 'Content-Type': 'application/json' };
    aiBody = { model: b.aiModel, temperature: 0, max_tokens: 4000,
               response_format: { type: 'json_object' },
               messages: [{ role: 'system', content: system }, { role: 'user', content: instruction }] };
    break;
}

return { json: { userId: b.userId, jobs: b.jobs, aiUrl, aiHeaders, aiBody } };

// One parser for all four providers: pull the text out of whichever envelope
// came back, then read the same JSON contract from it.
const response = $input.item.json;
const request = $('Build Scoring Request').item.json;
const jobs = request.jobs || [];

function extractText(r) {
  if (Array.isArray(r.content)) return r.content.filter(b => b && b.type === 'text').map(b => b.text).join('');
  if (r.choices && r.choices[0]) return r.choices[0].message ? r.choices[0].message.content : r.choices[0].text;
  if (Array.isArray(r.candidates) && r.candidates[0]) {
    const parts = r.candidates[0].content && r.candidates[0].content.parts;
    if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  }
  return '';
}

let results = [];
const text = extractText(response) || '';
if (!text) {
  console.log('Scoring failed: ' + JSON.stringify(response).substring(0, 300));
} else {
  try {
    let parsed;
    try { parsed = JSON.parse(text); }
    catch (e) { const m = text.match(/\{[\s\S]*\}/); if (m) parsed = JSON.parse(m[0]); }
    if (parsed) results = parsed.results || (Array.isArray(parsed) ? parsed : []);
  } catch (e) { console.log('Parse error: ' + e.message); }
}

const byIndex = new Map();
for (const r of results) if (r && typeof r.i === 'number') byIndex.set(r.i, r);

// Irrelevant jobs are still recorded, at their real score. Writing the row is
// what stops this user being charged to score the same job again tomorrow.
const SENIORITY = ['junior', 'mid', 'senior', 'lead'];
const now = new Date().toISOString();

const matches = jobs.map((job, i) => {
  const r = byIndex.get(i) || {};
  const scored = byIndex.has(i);
  return {
    user_id: request.userId,
    job_id: job.id,
    score: typeof r.score === 'number' ? Math.min(100, Math.max(0, Math.round(r.score))) : (scored ? 50 : 40),
    // The model is asked for all of this and the row used to keep only the
    // score, so the dashboard's "Why it matches your CV" panel had nothing to
    // render and jobs.tech_stack stayed empty on nearly every row.
    match_reason: typeof r.match_reason === 'string' ? r.match_reason.substring(0, 300) : null,
    tech_stack: Array.isArray(r.tech_stack) ? r.tech_stack.map(t => String(t).toLowerCase()).slice(0, 20) : [],
    seniority: SENIORITY.includes(r.seniority) ? r.seniority : null,
    is_relevant: r.is_relevant === false ? false : true,
    // Written whether or not the model answered for this row. It is what tells
    // the dashboard and match_candidate_jobs that this job has been looked at,
    // so a score of 0 reads as a verdict rather than as "pending".
    scored_at: now
  };
});

console.log('Built ' + matches.length + ' match row(s), ' + byIndex.size + ' scored by the model');
return [{ json: { matches, count: matches.length } }];
